"use client";

import React, { useState, useEffect } from 'react';

export default function ReviewsPage() {
  const [reviews, setReviews] = useState([]);
  const [selectedStar, setSelectedStar] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadReviews() {
      try {
        const res = await fetch('/api/reviews');
        const data = await res.json();
        if (data.reviews) setReviews(data.reviews);
      } catch (err) {
        console.error('Error loading reviews:', err);
      } finally {
        setLoading(false);
      }
    }
    loadReviews();
  }, []);

  const filteredReviews = selectedStar
    ? reviews.filter((r) => String(r.stars) === selectedStar)
    : reviews;

  const avgRating = reviews.length
    ? (reviews.reduce((acc, r) => acc + (r.stars || 5), 0) / reviews.length).toFixed(1)
    : '5.0';

  return (
    <div class="container mx-auto px-4 py-8 max-w-6xl">
      {/* Hero Banner */}
      <div class="glass-card p-8 md:p-12 text-center max-w-4xl mx-auto mb-8 shadow-2xl relative overflow-hidden">
        <span class="shadcn-badge-amber mb-3 inline-block">
          <i class="fa fa-star me-1 text-amber-500"></i>Verified Ratings
        </span>
        <h1 class="font-display text-4xl sm:text-5xl font-bold text-slate-900 mb-3">Customer Reviews</h1>
        <p class="text-slate-600 max-w-xl mx-auto text-sm sm:text-base leading-relaxed">
          Bloom with love — see real feedback, photos, and ratings from customers who ordered custom bouquets and gifts.
        </p>
      </div>

      {/* Stats Box */}
      <div class="glass-card p-6 md:p-8 mb-8 shadow-xl">
        <div class="grid grid-cols-1 md:grid-cols-3 gap-6 items-center">
          <div class="text-center p-6 rounded-2xl bg-rose-50 border border-rose-200/60">
            <div class="text-5xl font-bold text-rose-600 leading-none mb-2">{avgRating}</div>
            <div class="text-amber-400 text-lg mb-1">★★★★★</div>
            <div class="text-xs text-slate-500 font-semibold uppercase tracking-wider">Average Rating</div>
          </div>

          <div class="text-center">
            <div class="text-3xl font-bold text-slate-900 mb-1">{reviews.length}</div>
            <div class="text-xs text-slate-500 font-semibold uppercase tracking-wider">Verified Customer Reviews</div>
          </div>

          <div>
            <label class="font-semibold text-xs text-slate-700 mb-1.5 block">Filter by Star Rating</label>
            <select
              value={selectedStar}
              onChange={(e) => setSelectedStar(e.target.value)}
              class="shadcn-input"
            >
              <option value="">All Ratings</option>
              <option value="5">★★★★★ (5 Stars)</option>
              <option value="4">★★★★☆ (4 Stars)</option>
              <option value="3">★★★☆☆ (3 Stars)</option>
              <option value="2">★★☆☆☆ (2 Stars)</option>
              <option value="1">★☆☆☆☆ (1 Star)</option>
            </select>
          </div>
        </div>
      </div>

      {/* Reviews Grid */}
      {loading ? (
        <div class="text-center py-12 text-slate-400">
          <i class="fa-solid fa-circle-notch fa-spin text-2xl text-rose-500 mb-2"></i>
          <p class="text-xs">Loading verified customer reviews...</p>
        </div>
      ) : filteredReviews.length === 0 ? (
        <div class="glass-card p-12 text-center text-slate-500 max-w-md mx-auto">
          <i class="fa-solid fa-star text-4xl text-amber-300 mb-3"></i>
          <h5 class="font-bold text-slate-800 text-base mb-1">No reviews found</h5>
          <p class="text-xs text-slate-500">There are no reviews matching the selected filter criteria.</p>
        </div>
      ) : (
        <div class="grid grid-cols-1 md:grid-cols-3 gap-6">
          {filteredReviews.map((r, idx) => (
            <div
              key={idx}
              class="glass-card h-full flex flex-col rounded-xl border border-slate-200/80 shadow-sm hover:shadow-md transition-all duration-300 overflow-hidden group hover:-translate-y-1"
            >
              {r.image_url && (
                <div class="relative w-full h-36 sm:h-40 overflow-hidden bg-slate-100 shrink-0">
                  <img
                    src={r.image_url}
                    alt="Review photo"
                    class="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
                    loading="lazy"
                  />
                </div>
              )}
              <div class="p-3.5 sm:p-4 flex flex-col flex-grow justify-between bg-white">
                <div>
                  <div class="flex items-center gap-2 mb-2">
                    <div class="w-7 h-7 rounded-full bg-gradient-to-tr from-rose-500 to-rose-400 text-white font-bold text-[11px] flex items-center justify-center shadow-sm uppercase shrink-0">
                      {(r.name || 'C').charAt(0)}
                    </div>
                    <h6 class="font-bold text-slate-900 text-xs sm:text-sm leading-tight mb-0 line-clamp-1">
                      {r.name}
                    </h6>
                  </div>

                  <div class="flex items-center gap-1 text-amber-400 text-[11px] mb-2">
                    {Array.from({ length: 5 }, (_, i) => (
                      <i
                        key={i}
                        class={`fa-solid fa-star ${i < (r.stars || 5) ? 'text-amber-400' : 'text-slate-200'}`}
                      ></i>
                    ))}
                  </div>

                  <p class="text-xs text-slate-600 leading-normal line-clamp-3 mb-0 italic">
                    "{r.message}"
                  </p>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
